import { describe, expect, it } from "vitest";
import {
  activeFilterCount,
  issueFilterQueryString,
  issueFilterToParams,
  parseIssueFilterParams,
  UNASSIGNED_TOKEN,
} from "@/hooks/issue-filter-params";
import type { LabelId, ProjectId, UserId } from "@/types/common";
import type { IssueFilter } from "@/types/issue";

function params(query: string): URLSearchParams {
  return new URLSearchParams(query);
}

describe("issue-filter-params/parse", () => {
  it("returns an empty filter for an empty query string", () => {
    expect(parseIssueFilterParams(params(""))).toEqual({});
  });

  it("parses comma-separated statuses and drops unknown values", () => {
    const filter = parseIssueFilterParams(params("status=todo,nonsense,done"));
    expect(filter.status).toEqual(["todo", "done"]);
  });

  it("distinguishes unassigned from no assignee filter", () => {
    expect(parseIssueFilterParams(params("assignee=none")).assigneeId).toBeNull();
    expect("assigneeId" in parseIssueFilterParams(params(""))).toBe(false);
  });

  it("reads the archived flag only for the literal 1", () => {
    expect(parseIssueFilterParams(params("archived=1")).includeArchived).toBe(
      true,
    );
    expect(
      parseIssueFilterParams(params("archived=true")).includeArchived,
    ).toBeUndefined();
  });
});

describe("issue-filter-params/serialise", () => {
  const filter: IssueFilter = {
    projectId: "prj_1" as ProjectId,
    status: ["todo", "in_progress"],
    assigneeId: "usr_1" as UserId,
    labelIds: ["lbl_1" as LabelId, "lbl_2" as LabelId],
    query: "crash",
    includeArchived: true,
  };

  it("round-trips through the query string", () => {
    const restored = parseIssueFilterParams(
      params(new URLSearchParams(issueFilterToParams(filter)).toString()),
    );
    expect(restored).toEqual(filter);
  });

  it("omits empty dimensions entirely", () => {
    expect(issueFilterToParams({ status: [], labelIds: [], query: "" })).toEqual(
      {},
    );
  });

  it("writes unassigned as the sentinel token", () => {
    expect(issueFilterToParams({ assigneeId: null }).assignee).toBe(
      UNASSIGNED_TOKEN,
    );
  });

  it("produces a bare path for an empty filter", () => {
    expect(issueFilterQueryString({})).toBe("");
    expect(issueFilterQueryString({ query: "x" })).toBe("?q=x");
  });

  it("counts the narrowed dimensions", () => {
    expect(activeFilterCount({})).toBe(0);
    expect(activeFilterCount(filter)).toBe(6);
  });
});
/** `createIssueSchema` defaults, bounds and error paths. */
import { describe, expect, it } from "vitest";
import {
  archiveIssueSchema,
  assignIssueSchema,
  changeIssueStatusSchema,
  createIssueSchema,
  issueFilterSchema,
  moveIssueSchema,
  updateIssueSchema,
} from "@/schemas/issue";
import { ISSUE_PRIORITIES, ISSUE_STATUSES } from "@/types/issue";
import { ALICE, ORG_A } from "../helpers/factories";

const PROJECT = "01HZZZPPPPPPPPPPPPPPPPPPPP";
const ISSUE = "01HZZZSSSSSSSSSSSSSSSSSSSS";

function createInput(overrides: Record<string, unknown> = {}) {
  return { orgId: ORG_A, projectId: PROJECT, title: "Fix the link", ...overrides };
}

describe("schemas/issue", () => {
  it("applies every documented default", () => {
    expect(createIssueSchema.parse(createInput())).toMatchObject({
      description: null,
      status: "backlog",
      priority: "none",
      assigneeId: null,
      parentId: null,
      estimate: null,
      dueAt: null,
      labelIds: [],
    });
  });

  it("accepts every status and priority in the domain", () => {
    for (const status of ISSUE_STATUSES) {
      expect(createIssueSchema.safeParse(createInput({ status })).success, status).toBe(
        true,
      );
    }
    for (const priority of ISSUE_PRIORITIES) {
      expect(
        createIssueSchema.safeParse(createInput({ priority })).success,
        priority,
      ).toBe(true);
    }
  });

  it("rejects a status outside the enum", () => {
    expect(createIssueSchema.safeParse(createInput({ status: "shipped" })).success).toBe(
      false,
    );
  });

  it("bounds the title at 3 and 200 characters, reporting the title path", () => {
    expect(createIssueSchema.safeParse(createInput({ title: "ab" })).success).toBe(false);
    expect(
      createIssueSchema.safeParse(createInput({ title: "a".repeat(201) })).success,
    ).toBe(false);

    const result = createIssueSchema.safeParse(createInput({ title: "ab" }));
    if (result.success) return;
    expect(result.error.issues[0]?.path).toEqual(["title"]);
    expect(result.error.issues[0]?.message).toBe("give the issue a title");
  });

  it("requires ULID ids and reports the offending path", () => {
    const result = createIssueSchema.safeParse(createInput({ projectId: "nope" }));
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.issues[0]?.path).toEqual(["projectId"]);
  });

  it("bounds the estimate to a whole number between 0 and 100", () => {
    expect(createIssueSchema.safeParse(createInput({ estimate: 8 })).success).toBe(true);
    expect(createIssueSchema.safeParse(createInput({ estimate: 1.5 })).success).toBe(
      false,
    );
    expect(createIssueSchema.safeParse(createInput({ estimate: 101 })).success).toBe(
