new='''/**
 * The URL is the single source of truth for the issue list filter: a filtered
 * view has to be shareable and survive a reload, and the server component that
 * renders the page parses the very same query string. These two functions are
 * that codec, kept pure so both sides can use them. ADR 0009 fixes the
 * vocabulary; the filter schema and the repository read the same one.
 *
 * `assignee=none` is the sanctioned spelling of "unassigned" — `undefined`
 * means "don't filter on assignee at all", which is a different query.
 * `assignee=me` / `author=me` travel unchanged: the service resolves them
 * against the acting user.
 */
import { dueBeforeSchema } from "@/schemas/common";
import type { LabelId, ProjectId, UserId } from "@/types/common";
import {
  CURRENT_USER_TOKEN,
  expandIssueStatuses,
  ISSUE_PRIORITIES,
  ISSUE_STATUSES,
  isIssueStatusGroup,
  type IssueFilter,
  type IssuePriority,
  type IssueStatusFilterValue,
} from "@/types/issue";

export const UNASSIGNED_TOKEN = "none";

export { CURRENT_USER_TOKEN };

export interface ReadableParams {
  get(name: string): string | null;
}

function splitList(raw: string | null): readonly string[] {
  if (raw === null || raw.length === 0) return [];
  const parts = raw
    .split(",")
    .map((part) => part.trim())
    .filter((part) => part.length > 0);
  return [...new Set(parts)];
}

/** An empty value is the same as an absent one: nothing to filter on. */
function present(raw: string | null): string | null {
  return raw === null || raw.length === 0 ? null : raw;
}

/**
 * Adapts the `searchParams` record Next hands a page to `ReadableParams`, so
 * pages go through the codec instead of reading the query string themselves.
 * A repeated parameter reads as the comma list of its values.
 */
export function paramsFromRecord(
  record: Readonly<Record<string, string | readonly string[] | undefined>>,
): ReadableParams {
  return {
    get(name) {
      const value = record[name];
      if (value === undefined) return null;
      return typeof value === "string" ? value : value.join(",");
    },
  };
}

export function parseIssueFilterParams(params: ReadableParams): IssueFilter {
  // `open` / `closed` expand here, so everything downstream of the codec sees
  // plain statuses; anything that is neither a status nor a group is dropped.
  const statuses = expandIssueStatuses(
    splitList(params.get("status")).filter(
      (value): value is IssueStatusFilterValue =>
        isIssueStatusGroup(value) ||
        (ISSUE_STATUSES as readonly string[]).includes(value),
    ),
  );
  const priorities = splitList(params.get("priority")).filter(
    (value): value is IssuePriority =>
      ISSUE_PRIORITIES.includes(value as IssuePriority),
  );
  const labelIds = splitList(params.get("label")) as readonly LabelId[];
  const project = present(params.get("project"));
  const assignee = present(params.get("assignee"));
  const author = present(params.get("author"));
  const query = params.get("q");
  const dueBefore = dueBeforeSchema.safeParse(params.get("due_before")?.trim());
  const archived = params.get("archived");

  const filter: IssueFilter = {
    ...(project !== null ? { projectId: project as ProjectId } : {}),
    ...(statuses.length > 0 ? { status: statuses } : {}),
    ...(priorities.length > 0 ? { priority: priorities } : {}),
    ...(assignee !== null
      ? {
          assigneeId:
            assignee === UNASSIGNED_TOKEN
              ? null
              : (assignee as UserId | typeof CURRENT_USER_TOKEN),
        }
      : {}),
    ...(author !== null
      ? { authorId: author as UserId | typeof CURRENT_USER_TOKEN }
      : {}),
    ...(labelIds.length > 0 ? { labelIds } : {}),
    ...(query !== null && query.length > 0 ? { query } : {}),
    ...(dueBefore.success ? { dueBefore: dueBefore.data } : {}),
    ...(archived === "1"
      ? { includeArchived: true as const }
      : archived === "only"
        ? { includeArchived: "only" as const }
        : {}),
  };

  return filter;
}

