cat > tests/components/issue-filter-vocabulary.test.ts <<'EOF'
/** ADR 0009: the URL codec side of the issue list filter vocabulary. */
import { describe, expect, it } from "vitest";
import {
  issueFilterToParams,
  paramsFromRecord,
  parseIssueFilterParams,
} from "@/hooks/issue-filter-params";
import { issueFilterSchema } from "@/schemas/issue";
import { ALICE, ORG_A } from "../helpers/factories";

function params(query: string): URLSearchParams {
  return new URLSearchParams(query);
}

describe("issue-filter-params/vocabulary", () => {
  it("expands the open and closed groups when parsing status", () => {
    expect(parseIssueFilterParams(params("status=open")).status).toEqual([
      "backlog",
      "todo",
      "in_progress",
      "in_review",
    ]);
    expect(parseIssueFilterParams(params("status=closed")).status).toEqual([
      "done",
      "canceled",
    ]);
  });

  it("merges groups with single statuses without duplicates", () => {
    expect(
      parseIssueFilterParams(params("status=todo,open,done,nonsense")).status,
    ).toEqual(["todo", "backlog", "in_progress", "in_review", "done"]);
  });

  it("carries me and none through unchanged", () => {
    expect(parseIssueFilterParams(params("assignee=me")).assigneeId).toBe("me");
    expect(parseIssueFilterParams(params("author=me")).authorId).toBe("me");
    expect(parseIssueFilterParams(params("assignee=none")).assigneeId).toBeNull();
    expect(issueFilterToParams({ assigneeId: "me" }).assignee).toBe("me");
  });

  it("treats an empty assignee as no filter", () => {
    expect("assigneeId" in parseIssueFilterParams(params("assignee="))).toBe(false);
  });

  it("reads archived=only as its own scope and round-trips it", () => {
    const filter = parseIssueFilterParams(params("archived=only"));
    expect(filter.includeArchived).toBe("only");
    expect(issueFilterToParams(filter)).toEqual({ archived: "only" });
  });

  it("keeps a calendar date or a full timestamp for due_before and drops junk", () => {
    expect(parseIssueFilterParams(params("due_before=2026-03-15")).dueBefore).toBe(
      "2026-03-15",
    );
    expect(
      parseIssueFilterParams(params("due_before=2026-03-15T08:30:00.000Z")).dueBefore,
    ).toBe("2026-03-15T08:30:00.000Z");
    expect("dueBefore" in parseIssueFilterParams(params("due_before=2026-02-30"))).toBe(
      false,
    );
    expect("dueBefore" in parseIssueFilterParams(params("due_before=soon"))).toBe(false);
  });

  it("reads a Next searchParams record like a URLSearchParams", () => {
    const filter = parseIssueFilterParams(
      paramsFromRecord({ status: ["todo", "done"], assignee: "me", q: undefined }),
    );
    expect(filter).toEqual({ status: ["todo", "done"], assigneeId: "me" });
  });

  it("only produces values the filter schema accepts", () => {
    const filter = parseIssueFilterParams(
      params(
        `status=open,closed&assignee=me&author=${ALICE}&due_before=2026-03-15&archived=only`,
      ),
    );
    expect(issueFilterSchema.safeParse({ orgId: ORG_A, ...filter }).success).toBe(
      true,
    );
  });
});

describe("issue filter schema/vocabulary", () => {
  it("accepts status groups, me, unassigned, dates and archived=only", () => {
    const result = issueFilterSchema.safeParse({
      orgId: ORG_A,
      status: ["open", "done"],
      assigneeId: "me",
      authorId: "me",
      dueBefore: "2026-03-15",
      includeArchived: "only",
    });
    expect(result.success).toBe(true);
    expect(
      issueFilterSchema.safeParse({ orgId: ORG_A, assigneeId: null }).success,
    ).toBe(true);
    expect(
      issueFilterSchema.safeParse({ orgId: ORG_A, dueBefore: "2026-03-15T00:00:00Z" })
        .success,
    ).toBe(true);
  });

  it("refuses unknown statuses, malformed dates and unknown archive scopes", () => {
    expect(
      issueFilterSchema.safeParse({ orgId: ORG_A, status: ["shipped"] }).success,
    ).toBe(false);
    expect(
      issueFilterSchema.safeParse({ orgId: ORG_A, dueBefore: "2026-02-30" }).success,
    ).toBe(false);
    expect(
      issueFilterSchema.safeParse({ orgId: ORG_A, dueBefore: "tomorrow" }).success,
    ).toBe(false);
    expect(
      issueFilterSchema.safeParse({ orgId: ORG_A, includeArchived: "all" }).success,
    ).toBe(false);
    expect(
      issueFilterSchema.safeParse({ orgId: ORG_A, assigneeId: "someone" }).success,
    ).toBe(false);
  });
});
