    const result = issueFilterSchema.safeParse({
      orgId: ORG_A,
      status: ["open", "done"],
      assigneeId: "me",
      authorId: "me",
      dueBefore: "2026-03-15",
      includeArchived: "only",
    });
    expect(result.success).toBe(true);
    expect(
      issueFilterSchema.safeParse({ orgId: ORG_A, assigneeId: null }).success,
    ).toBe(true);
    expect(
      issueFilterSchema.safeParse({ orgId: ORG_A, dueBefore: "2026-03-15T00:00:00Z" })
        .success,
    ).toBe(true);
  });

  it("refuses unknown statuses, malformed dates and unknown archive scopes", () => {
    expect(
      issueFilterSchema.safeParse({ orgId: ORG_A, status: ["shipped"] }).success,
    ).toBe(false);
