/**
 * ADR 0009 end to end: URL -> codec -> schema -> service -> repository, so
 * every entry point gives the same answer for the same filter.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { parseIssueFilterParams } from "@/hooks/issue-filter-params";
import { issueFilterSchema } from "@/schemas/issue";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as issueService from "@/server/services/issue-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IsoTimestamp, LabelId, UserId } from "@/types/common";
import type { IssueStatus } from "@/types/issue";

let cleanup: () => void;
let tenant: Tenant;
let bug: LabelId;
let regression: LabelId;

const titles = (page: { items: readonly { title: string }[] }) =>
  page.items.map((issue) => issue.title).sort();

async function seed(
  title: string,
  extra: Partial<{
    status: IssueStatus;
    assigneeId: UserId | null;
    dueAt: string | null;
    labelIds: LabelId[];
    archived: boolean;
  }> = {},
) {
  const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
  const issue = await issueRepo.insertIssue(
    {
      ...issueInput(tenant.org.id, tenant.project.id, {
        title,
        assigneeId: extra.assigneeId ?? null,
        dueAt: extra.dueAt ?? null,
      }),
      status: extra.status ?? "backlog",
      labelIds: extra.labelIds ?? [],
    },
    tenant.userIds.owner,
    number,
  );
  if (extra.archived) await issueRepo.archiveIssue(tenant.org.id, issue.id);
  return issue;
}

/** What a page does: read the URL with the codec, validate, ask the service. */
async function listByUrl(query: string, actor = tenant.actors.member) {
  const filter = issueFilterSchema.parse({
    ...parseIssueFilterParams(new URLSearchParams(query)),
    orgId: tenant.org.id,
    limit: 100,
  });
  return issueService.listIssues(actor, filter);
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("filters");

  bug = (
    await labelRepo.insertLabel({
      orgId: tenant.org.id,
      name: "bug",
      color: "#ef4444",
      description: null,
    })
  ).id;
  regression = (
    await labelRepo.insertLabel({
      orgId: tenant.org.id,
      name: "regression",
      color: "#f59e0b",
      description: null,
    })
  ).id;

  const me = tenant.userIds.member;
  const other = tenant.userIds.admin;

  await seed("mine-todo", { status: "todo", assigneeId: me });
  await seed("mine-done", { status: "done", assigneeId: me });
  await seed("theirs-backlog", { status: "backlog", assigneeId: other });
  await seed("nobody-canceled", { status: "canceled" });
  await seed("nobody-review", { status: "in_review" });
  await seed("only-bug", { labelIds: [bug] });
  await seed("only-regression", { labelIds: [regression] });
  await seed("both-labels", { labelIds: [bug, regression] });
  await seed("due-early", { dueAt: "2026-03-14T09:00:00.000Z" });
  await seed("due-that-day-morning", { dueAt: "2026-03-15T00:00:00.000Z" });
  await seed("due-that-day-late", { dueAt: "2026-03-15T23:59:59.999Z" });
  await seed("due-next-midnight", { dueAt: "2026-03-16T00:00:00.000Z" });
  await seed("archived-one", { archived: true });
});

afterAll(() => {
  cleanup();
});

describe("issue list filter vocabulary (ADR 0009)", () => {
  it("assignee=me is the acting user's issues, whoever acts", async () => {
    const mine = await listByUrl("assignee=me");
    expect(titles(mine)).toEqual(["mine-done", "mine-todo"]);
    expect(mine.total).toBe(2);

    const theirs = await listByUrl("assignee=me", tenant.actors.admin);
    expect(titles(theirs)).toEqual(["theirs-backlog"]);
  });

  it("assignee=none lists only unassigned issues", async () => {
    const page = await listByUrl("assignee=none");
    expect(page.items.length).toBeGreaterThan(0);
    expect(page.items.every((issue) => issue.assigneeId === null)).toBe(true);
    expect(titles(page)).not.toContain("mine-todo");
    expect(page.total).toBe(page.items.length);
  });

  it("author=me resolves against the acting user", async () => {
    const owned = await listByUrl("author=me", tenant.actors.owner);
    expect(owned.total).toBeGreaterThan(0);
    const none = await listByUrl("author=me", tenant.actors.member);
    expect(none.total).toBe(0);
  });

  it("requires every listed label and counts the same rows", async () => {
    const page = await listByUrl(`label=${bug},${regression}`);
    expect(titles(page)).toEqual(["both-labels"]);
    expect(page.total).toBe(1);

    const single = await listByUrl(`label=${bug}`);
    expect(titles(single)).toEqual(["both-labels", "only-bug"]);
    expect(single.total).toBe(2);
  });

  it("includes the whole day for a calendar date and excludes later ones", async () => {
    const page = await listByUrl("due_before=2026-03-15");
    expect(titles(page)).toEqual([
      "due-early",
      "due-that-day-late",
      "due-that-day-morning",
    ]);
    expect(page.total).toBe(3);
  });

  it("keeps a full timestamp strictly before that instant", async () => {
    const page = await listByUrl("due_before=2026-03-15T00:00:00.000Z");
    expect(titles(page)).toEqual(["due-early"]);
    const offset = await listByUrl("due_before=2026-03-15T09:00:00.000%2B09:00");
    expect(titles(offset)).toEqual(["due-early"]);
  });

  it("treats status=open as every non-closed status, in URL and API alike", async () => {
    const byUrl = await listByUrl("status=open&assignee=none");
    expect(titles(byUrl)).not.toContain("nobody-canceled");
    expect(titles(byUrl)).toContain("nobody-review");

    const byApi = await issueService.listIssues(
      tenant.actors.member,
      issueFilterSchema.parse({
        orgId: tenant.org.id,
        status: ["open"],
        assigneeId: null,
        limit: 100,
      }),
    );
    expect(titles(byApi)).toEqual(titles(byUrl));
    expect(byApi.total).toBe(byUrl.total);

    const closed = await listByUrl("status=closed&assignee=none");
    expect(titles(closed)).toEqual(["nobody-canceled"]);
  });

  it("lists archived issues alone, with live ones for archived=1", async () => {
    const live = await listByUrl("");
    expect(titles(live)).not.toContain("archived-one");

    const only = await listByUrl("archived=only");
    expect(titles(only)).toEqual(["archived-one"]);
    expect(only.total).toBe(1);

    const both = await listByUrl("archived=1");
    expect(titles(both)).toContain("archived-one");
    expect(titles(both)).toContain("mine-todo");
    expect(both.total).toBe(live.total + 1);
  });

  it("reports a total that ignores the page size", async () => {
    const filter = issueFilterSchema.parse({
      orgId: tenant.org.id,
      status: ["open"],
      limit: 2,
    });
    const page = await issueService.listIssues(tenant.actors.member, filter);
    expect(page.items).toHaveLength(2);
    expect(page.total).toBeGreaterThan(2);
    const everything = await listByUrl("status=open");
    expect(page.total).toBe(everything.items.length);
  });

  it("the repository alone understands status groups and null assignee", async () => {
    const page = await issueRepo.listIssues({
      orgId: tenant.org.id,
      limit: 100,
      status: ["closed"],
      assigneeId: null,
      dueBefore: "2026-03-15" as IsoTimestamp,
    });
    expect(titles(page)).toEqual(["nobody-canceled"].filter(() => false));
  });
});
EOF
