import { parseIssueFilterParams } from "@/hooks/issue-filter-params";
import type { FeatureFlagSnapshot } from "@/types/feature-flag";
import { makeActor, makeOrganization } from "../helpers/factories";

afterEach(cleanup);

const FLAGS: FeatureFlagSnapshot = {
  kanban_board: true,
  ai_issue_summary: false,
  command_palette: false,
  activity_feed: true,
  public_projects: false,
  webhooks: false,
  csv_export: false,
  digest_email: false,
  issue_templates: false,
  advanced_search: true,
};

describe("components/app-sidebar — filter links", () => {
  it("keeps the query of 'Assigned to me' a query instead of encoding it into the path", () => {
    const org = makeOrganization();
    const actor = makeActor({ role: "owner", orgId: org.id });

    render(
      <AppSidebar
        org={org}
        actor={actor}
        flags={FLAGS}
        projects={[]}
        pathname={`/${org.slug}/issues`}
